"""Auth workspace layouts with a single duration-based license control."""

import re

APP_CONTENT = r'''<main class="auth-workspace">
<a class="workspace-back" href="/auth">← All apps</a>
<div class="workspace-heading"><div><div class="section-title">AUTH WORKSPACE</div><h1>{{ auth_app.name }}</h1><p class="muted">Manage access, issue licenses, and keep your users organized.</p></div><span class="workspace-app-id">APP {{ auth_app.id }}</span></div>
<div class="account-metrics"><div><span>Accounts</span><strong>{{ account_stats.total }}</strong></div><div><span>Awaiting activation</span><strong>{{ account_stats.pending }}</strong></div><div><span>Expired</span><strong>{{ account_stats.expired }}</strong></div><div><span>Disabled</span><strong>{{ account_stats.disabled }}</strong></div></div>
{% if notice %}<div class="notice" role="status">{{ {'user-deleted':'User deleted.','status-saved':'User status updated.','password-saved':'Password updated.','password-unavailable':'This account does not use a password.','renamed':'App renamed.'}.get(notice, notice) }}</div>{% endif %}
{% if error %}<div class="notice" role="alert">{{ {'expiry':'Choose a license duration from 0 to 36500 days.','password':'Use a password with at least 8 characters.','duplicate-user':'That username is already used in this app.','user-fields':'Enter a username and choose an authentication method.','key-rotate':'This user does not have a product key.','invalid-name':'Enter an app name.'}.get(error, 'Please check the form and try again.') }}</div>{% endif %}
{% if one_time_api_key %}<section class="form-card user-key-card"><div class="key-eyebrow">APP SERVER CREDENTIAL</div><h2>Copy your new API key</h2><p class="muted">The previous key is revoked. Copy this key now; it is shown once.</p><code class="secret-key">{{ one_time_api_key }}</code></section>{% endif %}
{% if one_time_product_key %}<section class="form-card user-key-card"><div class="key-eyebrow">USER PRODUCT KEY</div><h2>{{ one_time_product_key_username }}'s key is ready</h2><p class="muted">This key is unique to this user. Copy it now; it is shown once.</p><code class="secret-key">{{ one_time_product_key }}</code></section>{% endif %}
<div class="workspace-columns"><div class="workspace-users">
<section class="form-card workspace-filter"><div class="workspace-section-heading"><h2>Your users</h2><span>{{ users|length }} of {{ total_users }} shown</span></div><form method="get" class="workspace-filter-form"><input class="text-input" type="search" name="q" value="{{ search_query }}" placeholder="Search username or ID" aria-label="Search users"><select class="text-input" name="status" aria-label="Account status">{% for value,label in [('','All statuses'),('active','Active'),('pending','Not activated'),('expired','Expired'),('disabled','Disabled')] %}<option value="{{ value }}" {% if status_filter == value %}selected{% endif %}>{{ label }}</option>{% endfor %}</select><select class="text-input" name="mode" aria-label="Authentication method">{% for value,label in [('','All methods'),('password','Password'),('product_key','Product key'),('both','Password + key')] %}<option value="{{ value }}" {% if mode_filter == value %}selected{% endif %}>{{ label }}</option>{% endfor %}</select><button class="button" type="submit">Search</button>{% if search_query or status_filter or mode_filter %}<a class="plain" href="/auth/apps/{{ auth_app.id }}">Clear</a>{% endif %}</form>
<form id="bulk-users" method="post" action="/auth/apps/{{ auth_app.id }}/users/bulk" class="workspace-bulk"><input type="hidden" name="csrf" value="{{ csrf }}"><label class="select-users"><input type="checkbox" id="select-all-users"> Select all</label><span id="selected-count">0 selected</span><select class="text-input" name="action" aria-label="Bulk action"><option value="enable">Enable</option><option value="disable">Disable</option><option value="extend">Extend license</option><option value="delete">Delete</option></select><label class="bulk-days">Days<input class="text-input" type="number" name="days" value="30" min="1" max="36500" required></label><button class="button" type="submit">Apply</button></form></section>
<div class="section-title">Users · {{ users|length }}</div>
{% if users %}<div class="auth-user-list workspace-user-list">{% for user in users %}
<section class="form-card auth-user-card workspace-user-card"><div class="account-card-top"><div class="account-identity"><input form="bulk-users" type="checkbox" name="user_ids" value="{{ user.id }}" aria-label="Select {{ user.username }}"><span class="account-avatar" aria-hidden="true">{{ user.username[:1]|upper }}</span><div><strong>{{ user.username }}</strong><span class="account-id">ID {{ user.id }} · {{ {'password':'Password','product_key':'Product key','both':'Password + key'}[user.auth_mode] }}</span></div></div><span class="status-pill {{ user.display_status }}">{{ {'active':'Active','pending':'Not activated','expired':'Expired','disabled':'Disabled'}[user.display_status] }}</span></div>
<div class="account-license"><div><span class="account-caption">LICENSE</span><strong>{% if user.duration_days %}{{ user.duration_days }} days{% elif user.expires_at %}Timed license{% else %}Lifetime{% endif %}</strong></div><div class="license-remaining">{% if user.display_status == 'pending' %}<strong>Ready to activate</strong><span>Starts on first login</span>{% elif user.expires_at %}<strong>{% if user.days_left %}{{ user.days_left }} days left{% else %}License ended{% endif %}</strong><span>Ends {{ user.expires_at|int|datetime }} UTC</span>{% else %}<strong>Unlimited access</strong><span>No time limit</span>{% endif %}</div></div>
<div class="account-footer"><span>{% if user.last_login %}Last login {{ user.last_login|int|datetime }}{% else %}No logins yet{% endif %}</span><div class="auth-actions"><form method="post" action="/auth/apps/{{ auth_app.id }}/users/{{ user.id }}/toggle"><input type="hidden" name="csrf" value="{{ csrf }}"><button class="button" type="submit">{% if user.status == 'active' %}Disable{% else %}Enable{% endif %}</button></form><form method="post" action="/auth/apps/{{ auth_app.id }}/users/{{ user.id }}/delete" onsubmit="return confirm('Delete this user permanently?')"><input type="hidden" name="csrf" value="{{ csrf }}"><button class="delete" type="submit">Delete</button></form></div></div>
<details class="account-editor"><summary>Manage license and credentials</summary><form class="auth-expiry license-form" method="post" action="/auth/apps/{{ auth_app.id }}/users/{{ user.id }}/license"><input type="hidden" name="csrf" value="{{ csrf }}"><label>License duration in days · 0 means lifetime<input class="text-input" type="number" name="duration_days" value="{{ user.duration_days or user.days_left or 0 }}" min="0" max="36500" required></label><button class="button" type="submit">Update license</button></form><p class="hint">Unactivated accounts start on first login. Updating an activated license starts this duration from today.</p>{% if user.auth_mode in ['password','both'] %}<form class="auth-expiry" method="post" action="/auth/apps/{{ auth_app.id }}/users/{{ user.id }}/password"><input type="hidden" name="csrf" value="{{ csrf }}"><label>New password<input class="text-input" type="password" name="password" minlength="8" autocomplete="new-password" required></label><button class="button" type="submit">Reset password</button></form>{% endif %}{% if user.auth_mode in ['product_key','both'] %}<form class="auth-action" method="post" action="/auth/apps/{{ auth_app.id }}/users/{{ user.id }}/rotate-key" onsubmit="return confirm('Replace this user’s product key and revoke their current key?')"><input type="hidden" name="csrf" value="{{ csrf }}"><button class="button" type="submit">Replace product key</button></form>{% endif %}</details></section>
{% endfor %}</div>{% else %}<section class="form-card empty"><h2>No users found</h2><p>Adjust the filters or create your first user.</p></section>{% endif %}</div>
<aside class="workspace-sidebar"><section class="form-card create-user-card"><div class="key-eyebrow">ADD ACCESS</div><h2>Create a user</h2><p class="muted">One account, one individual license.</p><form method="post" action="/auth/apps/{{ auth_app.id }}/users/create"><input type="hidden" name="csrf" value="{{ csrf }}"><div class="auth-user-create"><label>Username<input class="text-input" name="username" maxlength="80" placeholder="e.g. alex" required></label><label>Authentication<select class="text-input" name="auth_mode"><option value="product_key">Product key</option><option value="password">Username + password</option><option value="both">Password + product key</option></select></label><label>Password<input class="text-input" type="password" name="password" autocomplete="new-password" minlength="8" placeholder="At least 8 characters"></label><label>License duration<select class="text-input" name="duration_days"><option value="7">7 days</option><option value="30" selected>30 days</option><option value="90">90 days</option><option value="365">365 days</option><option value="0">Lifetime</option></select></label></div><p class="license-note">Timed licenses start on the first successful login.</p><button class="button primary" type="submit">Create user →</button></form></section>
<section class="form-card workspace-secondary"><details><summary>Generate multiple users</summary><form class="settings-form" method="post" action="/auth/apps/{{ auth_app.id }}/users/batch-create"><input type="hidden" name="csrf" value="{{ csrf }}"><label>Number of users<input class="text-input" name="count" type="number" value="10" min="1" max="100" required></label><label>Authentication<select class="text-input" name="auth_mode"><option value="product_key">Product key</option><option value="password">Password</option><option value="both">Password + key</option></select></label><label>License duration<select class="text-input" name="duration_days"><option value="7">7 days</option><option value="30" selected>30 days</option><option value="90">90 days</option><option value="365">365 days</option><option value="0">Lifetime</option></select></label><button class="button" type="submit">Generate accounts</button></form><p class="hint">Unique credentials are shown once after creation.</p></details></section>
<section class="form-card workspace-secondary"><details><summary>App configuration</summary><p class="hint">App API keys identify your server. Product keys belong to individual users.</p><p class="account-caption">AUTH ENDPOINT</p><code class="workspace-endpoint">{{ auth_app.api_url }}</code><form class="settings-form" method="post" action="/auth/apps/{{ auth_app.id }}/rename"><input type="hidden" name="csrf" value="{{ csrf }}"><label>App name<input class="text-input" name="name" value="{{ auth_app.name }}" maxlength="80" required></label><button class="button" type="submit">Save name</button></form><form class="auth-action" method="post" action="/auth/apps/{{ auth_app.id }}/rotate-key" onsubmit="return confirm('Revoke the current app API key and generate a new one?')"><input type="hidden" name="csrf" value="{{ csrf }}"><button class="button" type="submit">Replace API key</button></form><form class="auth-action" method="post" action="/auth/apps/{{ auth_app.id }}/delete" onsubmit="return confirm('Delete this app and every account in it?')"><input type="hidden" name="csrf" value="{{ csrf }}"><button class="delete" type="submit">Delete app</button></form></details></section><a class="workspace-doc-link" href="/api-docs">View API documentation ↗</a></aside></div></main>'''


def app_workspace(source):
    content = APP_CONTENT.replace('user.expires_at|int|datetime', 'user.expires_at|int|utc_datetime')
    return re.sub(r'<main>.*?</main>', lambda _: content, source, count=1, flags=re.S)


HOME_CONTENT = r'''<main class="auth-workspace auth-overview"><div class="workspace-heading"><div><div class="section-title">AUTHENTICATION</div><h1>Your access center</h1><p class="muted">Create apps. Issue licenses. Manage who gets in.</p></div><span class="workspace-app-id">{{ auth_apps|length }} APPS</span></div>{% if notice %}<div class="notice" role="status">{{ 'App deleted.' if notice == 'deleted' else notice }}</div>{% endif %}{% if error %}<div class="notice" role="alert">Enter an app name.</div>{% endif %}{% if one_time_api_key %}<section class="form-card user-key-card"><div class="key-eyebrow">APP SERVER CREDENTIAL</div><h2>Your app is ready</h2><p class="muted">Copy this API key now. Each user will get their own product key when you create their account.</p><code class="secret-key">{{ one_time_api_key }}</code></section>{% endif %}<section class="form-card app-create-strip"><div><h2>Create an app</h2><p class="muted">A separate space for your users and licenses.</p></div><form class="auth-create" method="post" action="/auth/apps/create"><input type="hidden" name="csrf" value="{{ csrf }}"><input class="text-input" name="name" placeholder="e.g. My application" aria-label="App name" maxlength="80" required><button class="button primary" type="submit">Create app →</button></form></section><div class="workspace-section-heading overview-list-heading"><h2>Your applications</h2><span>{{ auth_apps|map(attribute='user_count')|sum }} total users</span></div>{% if auth_apps %}<section class="cards overview-apps">{% for item in auth_apps %}<a class="hookbox overview-app-card" href="/auth/apps/{{ item.id }}"><div><span class="app-tile-icon" aria-hidden="true"><svg class="icon" viewBox="0 0 24 24"><path d="M12 3 4 7v5c0 5 3 8 8 10 5-2 8-5 8-10V7z"/><path d="m9 12 2 2 4-4"/></svg></span><div class="hook-name">{{ item.name }}</div><div class="hook-path">APP {{ item.id }}</div><div class="hook-count">{{ item.user_count }} users</div></div><div class="arrow">↗</div></a>{% endfor %}</section>{% else %}<section class="form-card empty"><h2>Your first app starts here</h2><p>Create an app above, then add users and choose their license durations.</p></section>{% endif %}</main>'''


def home_workspace(source):
    return re.sub(r'<main>.*?</main>', lambda _: HOME_CONTENT, source, count=1, flags=re.S)
